import { EventEmitter } from 'eventemitter3';
import { debounce, FORMAT_TIME_DEFAULT_THRESHOLDS, formatCurrency, formatTimeWithPrecision } from '@game-studio/utilities';
import FormComponent from './components/form/index.vue';
import HelpComponent from './components/help/index.vue';
import LimitApproaching from './components/limit-approaching/index.vue';
import PrimaryPopup from './components/primary-popup/index.vue';
import ProgressDetails from './components/progress-details/index.vue';
import RestrictionComponent from './components/restriction/index.vue';
import SecondaryPopup from './components/secondary-popup/index.vue';
import SessionEnded from './components/session-ended/index.vue';
import { ISessionManagementConfig, ISessionManagementEvents, ISessionModel, ISessionSettings, ISessionStatus } from './types';
import { Component, Prop, Provide, Vue, Watch } from 'vue-property-decorator';
import { ISubGameSessionInfo } from '@game-studio/server-comms';

interface IPrimaryPopupVisibilities {
    [key: string]: boolean;
    createSessionPopup: boolean;
    confirmSessionPopup: boolean;
    restrictionPopup: boolean;
}

interface ISecondaryPopupVisibilities {
    [key: string]: boolean;
    progressAlertPopup: boolean;
    limitApproachingPopup: boolean;
    sessionEndedPopup: boolean;
}

export const DEFAULT_SESSION_MODEL: ISessionModel = {
    maxTime: -1,
    maxBet: -1,
    alertFrequency: 3600, // New default is now one hour intervals, without options
    sessionRestriction: 0,
    freePlayBalance: -1
};

@Component({
    components: { FormComponent, LimitApproaching, HelpComponent, RestrictionComponent, SecondaryPopup, SessionEnded, ProgressDetails, PrimaryPopup },
})
export default class SessionManagement extends Vue {
    public $refs: Vue['$refs'] & {
        createSessionPopup: FormComponent,
        confirmSessionPopup: FormComponent,
        restrictionPopup: RestrictionComponent,
        limitApproachingPopup: LimitApproaching,
        progressAlertPopup: ProgressDetails,
        sessionEndedPopup: SessionEnded
    };

    @Prop()
    public readonly sessionSettings: ISessionSettings;

    public helpText: string = '';
    public networkPending: boolean = false;
    public progressOpen: boolean = false;
    public confirmationPending: boolean = false;
    public formForceClosed: boolean = true;

    @Prop()
    public readonly externalPageNavigation: (url: string) => void;

    @Prop()
    public readonly config: ISessionManagementConfig;

    @Prop()
    public readonly sessionStatus: ISessionStatus;

    @Prop()
    public readonly gameInProgress: boolean;

    @Prop()
    public readonly currentBalance: number;

    @Provide()
    @Prop()
    public readonly events: EventEmitter<ISessionManagementEvents>;

    public sessionDuration: number = 0;
    private sessionModel: ISessionModel = Object.assign({}, DEFAULT_SESSION_MODEL);
    private hadActiveSession: boolean = false;
    private debouncedConfirmation: () => void;
    private startTime: number;

    private sessionTicker: number;

    private primaryPopupVisibilities: IPrimaryPopupVisibilities = {
        createSessionPopup: false,
        confirmSessionPopup: false,
        restrictionPopup: false
    };

    private secondaryPopupVisibilities: ISecondaryPopupVisibilities = {
        progressAlertPopup: false,
        limitApproachingPopup: false,
        sessionEndedPopup: false,
    };

    get suppressForm(): boolean {
        return this.gameInProgress || this.secondaryPopupVisibilities.sessionEndedPopup;
    }

    get primaryPopupIsOpen(): boolean {
        const values: boolean[] = [];
        Object.keys(this.primaryPopupVisibilities).forEach((key) => {
            values.push(this.primaryPopupVisibilities[key]);
        });
        return values.filter((bool) => bool).length > 0;
    }

    get secondaryPopupIsOpen(): boolean {
        const values: boolean[] = [];
        Object.keys(this.secondaryPopupVisibilities).forEach((key) => {
            values.push(this.secondaryPopupVisibilities[key]);
        });
        return values.filter((bool) => bool).length > 0;
    }

    get createFormPriorityAlertsVisible(): boolean {
        return (this.primaryPopupVisibilities.restrictionPopup);
    }

    get progressAlertPopupPriorityAlertsVisible(): boolean {
        return this.secondaryPopupVisibilities.limitApproachingPopup;
    }

    get sessionEndedRecently(): boolean {
        const recently = this.config.sessionEndedWindow;

        if (this.sessionStatus.SessionEnded && this.sessionStatus.SessionId > 0) {
            if (this.sessionDuration - this.sessionStatus.MaxTime < recently) {
                return true;
            }
        }

        return false;
    }

    // Lifecycle events

    public created(): void {
        this.setupSessionTicker();
        this.formForceClosed = (!this.sessionStatus.SessionEnded || this.sessionEndedRecently);
        this.debouncedConfirmation = debounce(this.confirmation, 500);
    }

    public mounted(): void {
        this.events.on('session:form:show', (response) => {
            this.onShowForm(response);
        });

        this.events.on('session:form:hide', this.onFormClosed, this);
        document.addEventListener('visibilitychange', () => {
            this.onVisibilityChange(document.visibilityState);
        });

        this.updatedChildVisibility();
    }

    public updated(): void {
        this.updatedChildVisibility();
    }

    public destroyed(): void {
        this.clearSessionTicker();
        this.events.off('session:form:show', this.onShowForm, this, false);
        this.events.off('session:form:hide', this.onFormClosed, this, false);
    }

    // Helpers

    @Provide()
    public stringifyTime(seconds: number): string {
        const timeTranslations = this.config.translations.durations;

        return formatTimeWithPrecision(seconds, FORMAT_TIME_DEFAULT_THRESHOLDS, timeTranslations);
    }

    @Provide()
    public stringifyBet(bet: number): string {
        return formatCurrency(bet, this.config.currency);
    }

    // Data mutation events

    @Watch('sessionDuration')
    public onSessionDurationChanged(): void {
        if (this.sessionStatus.SessionEnded) {
            return;
        }

        const timeLeftInSession = (this.sessionStatus.MaxTime - this.sessionDuration);

        if (timeLeftInSession <= 0) {
            this.sessionStatus.SessionEnded = true;
            this.hadActiveSession = false;
        }
    }

    @Watch('sessionStatus', { immediate: true, deep: true })
    public onSessionStatusChanged(): void {
        this.networkPending = false;
        this.sessionDuration = this.sessionStatus.CurrentTime;
        this.startTime = Date.now() - (this.sessionStatus.CurrentTime * 1000);

        if (this.hadActiveSession !== !this.sessionStatus.SessionEnded) {
            this.hadActiveSession = !this.sessionStatus.SessionEnded;
        }

        if (!this.sessionStatus.SessionEnded) {
            this.confirmationPending = false;
        } else {
            this.events.emit('session:ended');
        }
    }

    // UI events

    public onFormSubmitted(): void {
        this.confirmationPending = true;
    }

    public confirmation(): void {
        this.events.emit('session:create', this.sessionModel);
        this.networkPending = true;
        this.closeForm();
        this.$forceUpdate();
    }

    public onConfirmationSubmitted(): void {
        this.debouncedConfirmation();
    }

    public onModifyLimits(): void {
        this.confirmationPending = false;
    }

    public onFormClosed(): void {
        this.closeForm();
    }

    public onSessionEndedClosed(): void {
        this.closeForm();
        this.events.emit('session:reset');
    }

    public onSessionRestrictedClosed(): void {
        this.closeForm();
    }

    public onUpdateHelpText(text: string): void {
        this.helpText = text;
    }

    public onShowForm(response?: ISubGameSessionInfo): void {
        const defaultSessionModel = this.config.defaultSessionModel ? this.config.defaultSessionModel : DEFAULT_SESSION_MODEL;
        Object.assign(this.sessionModel, { ...defaultSessionModel, freePlayBalance: response?.freePlayBalance ?? -1 });

        if (this.sessionStatus.SessionEnded) {
            this.formForceClosed = false;
        }
    }

    public onAlert(): void {
        this.events.emit('session:alert');
    }

    // Timers
    private setupSessionTicker(): void {
        if (!this.sessionTicker) {
            this.sessionTicker = window.setInterval(() => {
                this.sessionDuration = (Date.now() - this.startTime) / 1000;
            }, 1000);
        }
    }

    private onVisibilityChange(visibilityState: string): void {
        if (this.sessionStatus.SessionEnded) {
            return;
        }

        if (visibilityState === 'visible') {
            this.sessionDuration = (Date.now() - this.startTime) / 1000;
        }
    }

    private closeForm(): void {
        this.events.emit('session:closed');
        this.formForceClosed = true;
    }

    private clearSessionTicker(): void {
        if (this.sessionTicker) {
            window.clearInterval(this.sessionTicker);
        }
    }

    private updatedChildVisibility(): void {
        // $refs is not reactive, nor is it populated if the $ref is rendered with a v-if
        // we manually track this visibility states here so we can supress UI elements if a higher priority element is visible
        this.primaryPopupVisibilities.createSessionPopup = (this.$refs.createSessionPopup !== undefined && (this.$refs.createSessionPopup as any).visible);
        this.primaryPopupVisibilities.confirmSessionPopup = (this.$refs.confirmSessionPopup !== undefined && (this.$refs.confirmSessionPopup as any).visible);
        this.primaryPopupVisibilities.restrictionPopup = (this.$refs.restrictionPopup !== undefined && (this.$refs.restrictionPopup as any).visible);
        this.secondaryPopupVisibilities.progressAlertPopup = (this.$refs.progressAlertPopup !== undefined && (this.$refs.progressAlertPopup as any).visible);
        this.secondaryPopupVisibilities.limitApproachingPopup = (this.$refs.limitApproachingPopup !== undefined && (this.$refs.limitApproachingPopup as any).visible);
        this.secondaryPopupVisibilities.sessionEndedPopup = (this.$refs.sessionEndedPopup !== undefined && (this.$refs.sessionEndedPopup as any).visible);
    }
}